  const ui={role:'reception',lastPage:'/reception',drawerTime:null,dayOffset:0,calendarMode:'week',doctorFilter:'all',patientFilter:'all',patientSearch:'',resultFilter:'all',resultSelected:'r-01',profileTab:'overview',consultTab:'notes',consultId:'a-033',modal:null,notifications:false,toast:null};
